{
  "name": "google-drive-upload-api",
  "version": "1.0.0",
  "description": "Upload files to Google Drive via Google Drive API with OAuth 2.0",
  "main": "server/index.js",
  "scripts": {
    "dev": "node server/index.js",
    "start": "node server/index.js"
  },
  "keywords": ["google-drive", "upload", "oauth2"],
  "license": "MIT",
  "dependencies": {
    "dotenv": "^16.4.5",
    "express": "^4.21.0",
    "googleapis": "^144.0.0",
    "multer": "^1.4.5-lts.1"
  }
}

/**
 * Load and validate environment variables.
 * Never hard-code Client ID / Secret — all values come from .env
 */
require('dotenv').config();

function getEnv(name, required) {
  var value = process.env[name];
  if (required && (!value || String(value).trim() === '')) {
    return null;
  }
  return value ? String(value).trim() : '';
}

var config = {
  port: parseInt(process.env.PORT || '3000', 10),
  google: {
    clientId: getEnv('GOOGLE_CLIENT_ID', false),
    clientSecret: getEnv('GOOGLE_CLIENT_SECRET', false),
    redirectUri: getEnv('GOOGLE_REDIRECT_URI', false),
    refreshToken: getEnv('GOOGLE_REFRESH_TOKEN', false),
    driveFolderId: getEnv('GOOGLE_DRIVE_FOLDER_ID', false)
  }
};

/**
 * Check OAuth settings needed for auth routes
 */
config.hasOAuthCredentials = function () {
  return !!(this.google.clientId && this.google.clientSecret && this.google.redirectUri);
};

/**
 * Check settings needed for upload (refresh token + folder)
 */
config.canUpload = function () {
  return this.hasOAuthCredentials() &&
    !!this.google.refreshToken &&
    !!this.google.driveFolderId;
};

module.exports = config;

/**
 * Google OAuth2 client helpers — authorization URL, token exchange, authenticated Drive client
 */
var { google } = require('googleapis');
var config = require('./config');

var SCOPES = [
  'https://www.googleapis.com/auth/drive.file',
  'https://www.googleapis.com/auth/drive.metadata.readonly'
];

/**
 * Create OAuth2 client from .env (no hard-coded secrets)
 */
function createOAuth2Client() {
  if (!config.hasOAuthCredentials()) {
    throw new Error('Thiếu GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET hoặc GOOGLE_REDIRECT_URI trong file .env');
  }
  return new google.auth.OAuth2(
    config.google.clientId,
    config.google.clientSecret,
    config.google.redirectUri
  );
}

/**
 * Build URL to start Google login and get authorization code
 */
function getAuthUrl() {
  var oauth2Client = createOAuth2Client();
  return oauth2Client.generateAuthUrl({
    access_type: 'offline',
    prompt: 'consent',
    scope: SCOPES
  });
}

/**
 * Exchange authorization code for tokens (includes refresh_token on first consent)
 */
function exchangeCodeForTokens(code) {
  var oauth2Client = createOAuth2Client();
  return oauth2Client.getToken(code).then(function (response) {
    return response.tokens;
  });
}

/**
 * OAuth2 client with refresh token — used for Drive uploads
 */
function getAuthenticatedClient() {
  if (!config.canUpload()) {
    throw new Error(
      'Chưa cấu hình đủ để upload. Cần GOOGLE_REFRESH_TOKEN và GOOGLE_DRIVE_FOLDER_ID trong .env'
    );
  }
  var oauth2Client = createOAuth2Client();
  oauth2Client.setCredentials({
    refresh_token: config.google.refreshToken
  });
  return oauth2Client;
}

/**
 * Google Drive API v3 instance with refresh-token auth
 */
function getDriveClient() {
  var auth = getAuthenticatedClient();
  return google.drive({ version: 'v3', auth: auth });
}

module.exports = {
  SCOPES: SCOPES,
  createOAuth2Client: createOAuth2Client,
  getAuthUrl: getAuthUrl,
  exchangeCodeForTokens: exchangeCodeForTokens,
  getAuthenticatedClient: getAuthenticatedClient,
  getDriveClient: getDriveClient
};

/**
 * Upload files to Google Drive folder and map API response fields
 */
var fs = require('fs');
var path = require('path');
var { getDriveClient } = require('./googleAuth');
var config = require('./config');
var fileStore = require('./fileStore');

/**
 * Upload buffer/stream to folder GOOGLE_DRIVE_FOLDER_ID
 * @param {object} file - multer file { originalname, mimetype, size, path }
 * @returns {Promise<object>} fileId, fileName, webViewLink, webContentLink, size
 */
function uploadToDrive(file) {
  var drive = getDriveClient();
  var folderId = config.google.driveFolderId;

  var fileMetadata = {
    name: file.originalname,
    parents: [folderId]
  };

  var media = {
    mimeType: file.mimetype || 'application/octet-stream',
    body: fs.createReadStream(file.path)
  };

  return drive.files
    .create({
      resource: fileMetadata,
      media: media,
      fields: 'id, name, size, webViewLink, webContentLink, mimeType'
    })
    .then(function (res) {
      var data = res.data;
      var record = {
        fileId: data.id,
        fileName: data.name,
        webViewLink: data.webViewLink || buildFallbackViewLink(data.id),
        webContentLink: data.webContentLink || null,
        size: data.size ? parseInt(data.size, 10) : file.size,
        mimeType: data.mimeType || file.mimetype,
        uploadedAt: new Date().toISOString()
      };
      fileStore.add(record);
      return record;
    })
    .finally(function () {
      // Remove temp file after upload
      try {
        if (file.path && fs.existsSync(file.path)) {
          fs.unlinkSync(file.path);
        }
      } catch (e) {
        // ignore cleanup errors
      }
    });
}

function buildFallbackViewLink(fileId) {
  return 'https://drive.google.com/file/d/' + fileId + '/view';
}

/**
 * List files from local store (uploaded in this app session / persisted JSON)
 */
function listUploadedFiles() {
  return fileStore.getAll();
}

module.exports = {
  uploadToDrive: uploadToDrive,
  listUploadedFiles: listUploadedFiles
};

/**
 * Persist metadata of uploaded files (fileId, links, etc.) in data/uploads.json
 */
var fs = require('fs');
var path = require('path');

var DATA_DIR = path.join(__dirname, '..', 'data');
var DATA_FILE = path.join(DATA_DIR, 'uploads.json');

function ensureDataFile() {
  if (!fs.existsSync(DATA_DIR)) {
    fs.mkdirSync(DATA_DIR, { recursive: true });
  }
  if (!fs.existsSync(DATA_FILE)) {
    fs.writeFileSync(DATA_FILE, '[]', 'utf8');
  }
}

function readAll() {
  ensureDataFile();
  try {
    var raw = fs.readFileSync(DATA_FILE, 'utf8');
    var list = JSON.parse(raw);
    return Array.isArray(list) ? list : [];
  } catch (e) {
    return [];
  }
}

function writeAll(list) {
  ensureDataFile();
  fs.writeFileSync(DATA_FILE, JSON.stringify(list, null, 2), 'utf8');
}

function add(record) {
  var list = readAll();
  list.unshift(record);
  writeAll(list);
  return record;
}

function getAll() {
  return readAll();
}

module.exports = {
  add: add,
  getAll: getAll
};

/**
 * OAuth routes: login redirect, callback, exchange code for refresh token
 */
var express = require('express');
var config = require('../config');
var googleAuth = require('../googleAuth');

var router = express.Router();

/**
 * GET /auth/google — redirect user to Google consent screen
 */
router.get('/google', function (req, res) {
  try {
    if (!config.hasOAuthCredentials()) {
      return res.status(500).send(renderErrorPage(
        'Thiếu cấu hình OAuth',
        'Điền GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET, GOOGLE_REDIRECT_URI vào file .env'
      ));
    }
    var url = googleAuth.getAuthUrl();
    res.redirect(url);
  } catch (err) {
    res.status(500).send(renderErrorPage('Lỗi OAuth', err.message));
  }
});

/**
 * GET /auth/google/callback — Google redirects here with ?code=
 */
router.get('/google/callback', function (req, res) {
  var code = req.query.code;
  var error = req.query.error;

  if (error) {
    return res.status(400).send(renderErrorPage('Đăng nhập bị hủy', String(error)));
  }
  if (!code) {
    return res.status(400).send(renderErrorPage('Thiếu mã authorization', 'Không nhận được ?code= từ Google.'));
  }

  googleAuth
    .exchangeCodeForTokens(code)
    .then(function (tokens) {
      res.send(renderTokenPage(tokens));
    })
    .catch(function (err) {
      res.status(500).send(renderErrorPage('Đổi code thất bại', err.message));
    });
});

/**
 * POST /auth/exchange — programmatic exchange (optional, for API clients)
 * Body: { "code": "..." }
 */
router.post('/exchange', function (req, res) {
  var code = req.body && req.body.code;
  if (!code) {
    return res.status(400).json({ success: false, message: 'Thiếu trường code trong body JSON' });
  }

  googleAuth
    .exchangeCodeForTokens(code)
    .then(function (tokens) {
      res.json({
        success: true,
        access_token: tokens.access_token || null,
        refresh_token: tokens.refresh_token || null,
        expiry_date: tokens.expiry_date || null,
        scope: tokens.scope || null,
        message: tokens.refresh_token
          ? 'Copy GOOGLE_REFRESH_TOKEN vào file .env'
          : 'Không có refresh_token. Thử đăng nhập lại với prompt=consent hoặc revoke app tại https://myaccount.google.com/permissions'
      });
    })
    .catch(function (err) {
      res.status(500).json({ success: false, message: err.message });
    });
});

function renderTokenPage(tokens) {
  var refresh = tokens.refresh_token || '(không có — thử revoke quyền app và đăng nhập lại)';
  var access = tokens.access_token ? 'Có' : 'Không';
  return (
    '<!DOCTYPE html><html lang="vi"><head><meta charset="UTF-8">' +
    '<title>OAuth Token</title>' +
    '<script src="https://cdn.tailwindcss.com"></script></head>' +
    '<body class="bg-slate-900 text-slate-100 min-h-screen p-8">' +
    '<div class="max-w-2xl mx-auto bg-slate-800 rounded-xl p-6 shadow-xl">' +
    '<h1 class="text-2xl font-bold text-emerald-400 mb-4">Lấy Refresh Token thành công</h1>' +
    '<p class="mb-2">Access token: <strong>' + access + '</strong></p>' +
    '<p class="mb-4 text-sm text-slate-400">Copy giá trị bên dưới vào <code class="bg-slate-700 px-1 rounded">.env</code> → <code>GOOGLE_REFRESH_TOKEN</code></p>' +
    '<pre class="bg-slate-950 p-4 rounded-lg text-sm overflow-x-auto break-all text-emerald-300">' +
    escapeHtml(refresh) +
    '</pre>' +
    '<a href="/" class="inline-block mt-6 text-blue-400 hover:underline">← Về trang upload</a>' +
    '</div></body></html>'
  );
}

function renderErrorPage(title, message) {
  return (
    '<!DOCTYPE html><html lang="vi"><head><meta charset="UTF-8">' +
    '<title>Lỗi</title><script src="https://cdn.tailwindcss.com"></script></head>' +
    '<body class="bg-slate-900 text-slate-100 min-h-screen p-8">' +
    '<div class="max-w-xl mx-auto bg-red-900/30 border border-red-500 rounded-xl p-6">' +
    '<h1 class="text-xl font-bold text-red-300">' + escapeHtml(title) + '</h1>' +
    '<p class="mt-2 text-slate-300">' + escapeHtml(message) + '</p>' +
    '<a href="/" class="inline-block mt-4 text-blue-400">Về trang chủ</a></div></body></html>'
  );
}

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

module.exports = router;

/**
 * API routes: upload file, list uploaded files, health/config status
 */
var express = require('express');
var multer = require('multer');
var path = require('path');
var fs = require('fs');
var config = require('../config');
var driveService = require('../driveService');

var router = express.Router();

// Temp upload folder
var UPLOAD_DIR = path.join(__dirname, '..', '..', 'uploads');
if (!fs.existsSync(UPLOAD_DIR)) {
  fs.mkdirSync(UPLOAD_DIR, { recursive: true });
}

var storage = multer.diskStorage({
  destination: function (req, file, cb) {
    cb(null, UPLOAD_DIR);
  },
  filename: function (req, file, cb) {
    var unique = Date.now() + '-' + Math.round(Math.random() * 1e9);
    var safeName = file.originalname.replace(/[^\w.\-() ]/g, '_');
    cb(null, unique + '-' + safeName);
  }
});

var upload = multer({
  storage: storage,
  limits: { fileSize: 100 * 1024 * 1024 }
});

/**
 * GET /api/status — check env configuration (no secrets exposed)
 */
router.get('/status', function (req, res) {
  res.json({
    oauthConfigured: config.hasOAuthCredentials(),
    uploadReady: config.canUpload(),
    folderIdSet: !!config.google.driveFolderId,
    refreshTokenSet: !!config.google.refreshToken
  });
});

/**
 * POST /api/upload — multipart field name: "file"
 */
router.post('/upload', upload.single('file'), function (req, res) {
  if (!config.canUpload()) {
    return res.status(503).json({
      success: false,
      message:
        'Chưa sẵn sàng upload. Kiểm tra GOOGLE_REFRESH_TOKEN và GOOGLE_DRIVE_FOLDER_ID trong .env. ' +
        'Dùng /auth/google để lấy refresh token.'
    });
  }

  if (!req.file) {
    return res.status(400).json({ success: false, message: 'Không có file. Gửi field "file".' });
  }

  driveService
    .uploadToDrive(req.file)
    .then(function (result) {
      res.json({
        success: true,
        message: 'Upload thành công',
        data: {
          fileId: result.fileId,
          fileName: result.fileName,
          webViewLink: result.webViewLink,
          webContentLink: result.webContentLink,
          size: result.size
        }
      });
    })
    .catch(function (err) {
      res.status(500).json({
        success: false,
        message: err.message || 'Upload thất bại'
      });
    });
});

/**
 * GET /api/files — list files uploaded through this app
 */
router.get('/files', function (req, res) {
  try {
    var files = driveService.listUploadedFiles();
    res.json({ success: true, files: files });
  } catch (err) {
    res.status(500).json({ success: false, message: err.message });
  }
});

module.exports = router;

/**
 * Google Drive Upload API — Express server
 * Routes: static UI, OAuth, upload, file list
 */
var express = require('express');
var path = require('path');
var config = require('./config');
var authRoutes = require('./routes/auth');
var apiRoutes = require('./routes/api');

var app = express();

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Static frontend
var publicDir = path.join(__dirname, '..', 'public');
app.use(express.static(publicDir));

// OAuth
app.use('/auth', authRoutes);

// REST API
app.use('/api', apiRoutes);

// SPA fallback
app.get('/', function (req, res) {
  res.sendFile(path.join(publicDir, 'index.html'));
});

app.use(function (err, req, res, next) {
  console.error('[Error]', err.message);
  if (req.path.indexOf('/api') === 0) {
    return res.status(500).json({ success: false, message: err.message || 'Lỗi server' });
  }
  res.status(500).send('Lỗi server: ' + (err.message || 'unknown'));
});

var port = config.port;

app.listen(port, function () {
  console.log('');
  console.log('  Google Drive Upload API');
  console.log('  -----------------------');
  console.log('  Local:  http://localhost:' + port);
  console.log('  OAuth:  http://localhost:' + port + '/auth/google');
  console.log('');
  if (!config.hasOAuthCredentials()) {
    console.warn('  [!] Thiếu OAuth credentials trong .env');
  }
  if (!config.canUpload()) {
    console.warn('  [!] Upload chưa sẵn sàng — cần GOOGLE_REFRESH_TOKEN + GOOGLE_DRIVE_FOLDER_ID');
  } else {
    console.log('  [OK] Sẵn sàng upload vào Google Drive folder');
  }
  console.log('');
});

/* Drag-over state for drop zone */
.drop-zone.drag-over {
  border-color: rgb(99 102 241);
  background-color: rgba(99, 102, 241, 0.08);
  transform: scale(1.01);
}

.drop-zone {
  transition: border-color 0.2s, background-color 0.2s, transform 0.15s;
}

/* Toast enter animation */
.toast-enter {
  animation: toastIn 0.35s ease-out forwards;
}

@keyframes toastIn {
  from {
    opacity: 0;
    transform: translateX(1rem);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/**
 * Frontend: drag & drop, upload with progress, file list, notifications
 */
(function () {
  var dropZone = document.getElementById('dropZone');
  var fileInput = document.getElementById('fileInput');
  var selectedFileBox = document.getElementById('selectedFileBox');
  var selectedFileName = document.getElementById('selectedFileName');
  var selectedFileSize = document.getElementById('selectedFileSize');
  var clearFileBtn = document.getElementById('clearFileBtn');
  var uploadBtn = document.getElementById('uploadBtn');
  var progressWrap = document.getElementById('progressWrap');
  var progressBar = document.getElementById('progressBar');
  var progressPercent = document.getElementById('progressPercent');
  var progressLabel = document.getElementById('progressLabel');
  var filesList = document.getElementById('filesList');
  var filesEmpty = document.getElementById('filesEmpty');
  var refreshListBtn = document.getElementById('refreshListBtn');
  var configBadge = document.getElementById('configBadge');
  var toastContainer = document.getElementById('toastContainer');

  var selectedFile = null;

  function formatBytes(bytes) {
    if (!bytes && bytes !== 0) return '—';
    var units = ['B', 'KB', 'MB', 'GB'];
    var i = 0;
    var n = bytes;
    while (n >= 1024 && i < units.length - 1) {
      n /= 1024;
      i++;
    }
    return n.toFixed(i > 0 ? 1 : 0) + ' ' + units[i];
  }

  function showToast(message, type) {
    var colors = {
      success: 'bg-emerald-600/95 border-emerald-400',
      error: 'bg-red-600/95 border-red-400',
      info: 'bg-slate-700/95 border-slate-500'
    };
    var el = document.createElement('div');
    el.className =
      'toast-enter pointer-events-auto px-4 py-3 rounded-lg border text-sm shadow-lg ' +
      (colors[type] || colors.info);
    el.textContent = message;
    toastContainer.appendChild(el);
    setTimeout(function () {
      el.style.opacity = '0';
      el.style.transition = 'opacity 0.3s';
      setTimeout(function () {
        if (el.parentNode) el.parentNode.removeChild(el);
      }, 300);
    }, 4500);
  }

  function setSelectedFile(file) {
    selectedFile = file;
    if (!file) {
      selectedFileBox.classList.add('hidden');
      uploadBtn.disabled = true;
      fileInput.value = '';
      return;
    }
    selectedFileBox.classList.remove('hidden');
    selectedFileName.textContent = file.name;
    selectedFileSize.textContent = formatBytes(file.size);
    uploadBtn.disabled = false;
  }

  function handleFiles(fileList) {
    if (!fileList || !fileList.length) return;
    setSelectedFile(fileList[0]);
  }

  // Drag & drop
  ['dragenter', 'dragover'].forEach(function (ev) {
    dropZone.addEventListener(ev, function (e) {
      e.preventDefault();
      e.stopPropagation();
      dropZone.classList.add('drag-over');
    });
  });

  ['dragleave', 'drop'].forEach(function (ev) {
    dropZone.addEventListener(ev, function (e) {
      e.preventDefault();
      e.stopPropagation();
      dropZone.classList.remove('drag-over');
    });
  });

  dropZone.addEventListener('drop', function (e) {
    handleFiles(e.dataTransfer.files);
  });

  fileInput.addEventListener('change', function () {
    handleFiles(fileInput.files);
  });

  clearFileBtn.addEventListener('click', function () {
    setSelectedFile(null);
  });

  function setProgress(percent, label) {
    progressWrap.classList.remove('hidden');
    progressBar.style.width = percent + '%';
    progressPercent.textContent = Math.round(percent) + '%';
    if (label) progressLabel.textContent = label;
  }

  function hideProgress() {
    progressWrap.classList.add('hidden');
    progressBar.style.width = '0%';
    progressPercent.textContent = '0%';
  }

  function uploadFile(file) {
    return new Promise(function (resolve, reject) {
      var formData = new FormData();
      formData.append('file', file);

      var xhr = new XMLHttpRequest();
      xhr.open('POST', '/api/upload', true);

      xhr.upload.onprogress = function (e) {
        if (e.lengthComputable) {
          var pct = (e.loaded / e.total) * 100;
          setProgress(pct, 'Đang upload...');
        }
      };

      xhr.onload = function () {
        var body;
        try {
          body = JSON.parse(xhr.responseText);
        } catch (err) {
          return reject(new Error('Phản hồi server không hợp lệ'));
        }
        if (xhr.status >= 200 && xhr.status < 300 && body.success) {
          resolve(body);
        } else {
          reject(new Error(body.message || 'Upload thất bại'));
        }
      };

      xhr.onerror = function () {
        reject(new Error('Lỗi kết nối mạng'));
      };

      xhr.send(formData);
    });
  }

  uploadBtn.addEventListener('click', function () {
    if (!selectedFile) {
      showToast('Vui lòng chọn file trước', 'error');
      return;
    }

    uploadBtn.disabled = true;
    setProgress(0, 'Bắt đầu upload...');

    uploadFile(selectedFile)
      .then(function (res) {
        setProgress(100, 'Hoàn tất');
        showToast('Upload thành công: ' + res.data.fileName, 'success');
        setSelectedFile(null);
        loadFiles();
        setTimeout(hideProgress, 800);
      })
      .catch(function (err) {
        hideProgress();
        showToast(err.message || 'Upload thất bại', 'error');
      })
      .finally(function () {
        uploadBtn.disabled = !selectedFile;
      });
  });

  function renderFiles(files) {
    var items = filesList.querySelectorAll('.file-item');
    for (var i = 0; i < items.length; i++) {
      items[i].parentNode.removeChild(items[i]);
    }

    if (!files || !files.length) {
      filesEmpty.classList.remove('hidden');
      return;
    }

    filesEmpty.classList.add('hidden');

    files.forEach(function (f) {
      var row = document.createElement('div');
      row.className = 'file-item p-5 md:p-6 hover:bg-white/[0.02] transition';

      var viewLink = f.webViewLink || '#';
      var contentLink = f.webContentLink
        ? '<a href="' + escapeAttr(f.webContentLink) + '" target="_blank" rel="noopener" class="text-sm text-slate-400 hover:text-indigo-400">Tải xuống</a>'
        : '';

      row.innerHTML =
        '<div class="flex flex-col sm:flex-row sm:items-start justify-between gap-3">' +
        '<div class="min-w-0 flex-1">' +
        '<p class="font-medium text-slate-100 truncate">' + escapeHtml(f.fileName) + '</p>' +
        '<p class="text-sm text-slate-500 mt-1">' + formatBytes(f.size) + ' · ' + escapeHtml(f.fileId) + '</p>' +
        '<p class="text-xs text-slate-600 mt-1">' + escapeHtml(f.uploadedAt || '') + '</p>' +
        '</div>' +
        '<div class="flex flex-wrap gap-3 shrink-0">' +
        '<a href="' + escapeAttr(viewLink) + '" target="_blank" rel="noopener" class="text-sm font-medium text-indigo-400 hover:text-indigo-300">Mở trên Drive</a>' +
        contentLink +
        '</div></div>';

      filesList.appendChild(row);
    });
  }

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = s == null ? '' : String(s);
    return d.innerHTML;
  }

  function escapeAttr(s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/"/g, '&quot;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }

  function loadFiles() {
    fetch('/api/files')
      .then(function (r) {
        return r.json();
      })
      .then(function (data) {
        if (data.success) {
          renderFiles(data.files);
        }
      })
      .catch(function () {
        showToast('Không tải được danh sách file', 'error');
      });
  }

  function loadStatus() {
    fetch('/api/status')
      .then(function (r) {
        return r.json();
      })
      .then(function (s) {
        if (s.uploadReady) {
          configBadge.textContent = 'Sẵn sàng upload';
          configBadge.className =
            'text-xs px-3 py-1 rounded-full bg-emerald-500/20 text-emerald-400 border border-emerald-500/30';
        } else if (s.oauthConfigured) {
          configBadge.textContent = 'Cần refresh token / folder ID';
          configBadge.className =
            'text-xs px-3 py-1 rounded-full bg-amber-500/20 text-amber-400 border border-amber-500/30';
        } else {
          configBadge.textContent = 'Chưa cấu hình .env';
          configBadge.className =
            'text-xs px-3 py-1 rounded-full bg-red-500/20 text-red-400 border border-red-500/30';
        }
      })
      .catch(function () {
        configBadge.textContent = 'Server lỗi';
      });
  }

  refreshListBtn.addEventListener('click', loadFiles);

  loadStatus();
  loadFiles();
})();

