/**
 * Upload files / folders to Google Drive (GOOGLE_DRIVE_FOLDER_ID)
 */
var fs = require('fs');
var path = require('path');
var { getDriveClient } = require('./googleAuth');
var config = require('./config');
var fileStore = require('./fileStore');

/**
 * Parse duong dan tu originalname (client gui webkitRelativePath)
 */
function parseRelativePath(originalName) {
  var normalized = String(originalName || '').replace(/\\/g, '/');
  var parts = normalized.split('/').filter(function (p) {
    return p && p !== '.' && p !== '..';
  });
  if (!parts.length) {
    return { dirs: [], fileName: 'file' };
  }
  var fileName = parts.pop();
  return { dirs: parts, fileName: fileName };
}

function buildFallbackViewLink(fileId) {
  return 'https://drive.google.com/file/d/' + fileId + '/view';
}

function buildFallbackFolderLink(folderId) {
  return 'https://drive.google.com/drive/folders/' + folderId;
}

/**
 * Tao folder con tren Drive (co cache theo parentId + ten)
 */
function getOrCreateDriveFolder(drive, parentId, folderName, cache) {
  var cacheKey = parentId + '/' + folderName;
  if (cache[cacheKey]) {
    return Promise.resolve(cache[cacheKey]);
  }

  var metadata = {
    name: folderName,
    mimeType: 'application/vnd.google-apps.folder',
    parents: [parentId]
  };

  return drive.files
    .create({
      resource: metadata,
      fields: 'id, name, webViewLink'
    })
    .then(function (res) {
      var id = res.data.id;
      cache[cacheKey] = id;
      return id;
    });
}

/**
 * Dam bao day du thu muc con, tra ve folderId dich
 */
function ensureFolderPath(drive, rootFolderId, dirParts, cache) {
  var chain = Promise.resolve(rootFolderId);
  dirParts.forEach(function (dirName) {
    chain = chain.then(function (parentId) {
      return getOrCreateDriveFolder(drive, parentId, dirName, cache);
    });
  });
  return chain;
}

/**
 * Upload 1 file vao parentId
 */
function uploadFileToParent(drive, file, parentId, displayName) {
  var fileMetadata = {
    name: displayName,
    parents: [parentId]
  };

  var media = {
    mimeType: file.mimetype || 'application/octet-stream',
    body: fs.createReadStream(file.path)
  };

  return drive.files
    .create({
      resource: fileMetadata,
      media: media,
      fields: 'id, name, size, webViewLink, webContentLink, mimeType'
    })
    .then(function (res) {
      var data = res.data;
      var record = {
        fileId: data.id,
        fileName: data.name,
        relativePath: file.originalname,
        webViewLink: data.webViewLink || buildFallbackViewLink(data.id),
        webContentLink: data.webContentLink || null,
        size: data.size ? parseInt(data.size, 10) : file.size,
        mimeType: data.mimeType || file.mimetype,
        uploadedAt: new Date().toISOString()
      };
      fileStore.add(record);
      return record;
    })
    .finally(function () {
      try {
        if (file.path && fs.existsSync(file.path)) {
          fs.unlinkSync(file.path);
        }
      } catch (e) {
        // ignore cleanup errors
      }
    });
}

/**
 * Upload 1 file (co the kem duong dan thu muc trong originalname)
 */
function uploadToDriveWithPath(file) {
  var drive = getDriveClient();
  var rootFolderId = config.google.driveFolderId;
  var parsed = parseRelativePath(file.originalname);
  var cache = {};

  return ensureFolderPath(drive, rootFolderId, parsed.dirs, cache).then(function (parentId) {
    return uploadFileToParent(drive, file, parentId, parsed.fileName);
  });
}

/**
 * Upload nhieu file / ca folder (giu cau truc thu muc)
 */
function uploadBatch(files) {
  var drive = getDriveClient();
  var rootFolderId = config.google.driveFolderId;
  var cache = {};
  var results = [];
  var errors = [];

  var chain = Promise.resolve();

  files.forEach(function (file) {
    chain = chain.then(function () {
      var parsed = parseRelativePath(file.originalname);
      return ensureFolderPath(drive, rootFolderId, parsed.dirs, cache)
        .then(function (parentId) {
          return uploadFileToParent(drive, file, parentId, parsed.fileName);
        })
        .then(function (record) {
          results.push(record);
        })
        .catch(function (err) {
          errors.push({
            path: file.originalname,
            message: err.message || 'Upload thất bại'
          });
        });
    });
  });

  return chain.then(function () {
    return {
      total: files.length,
      succeeded: results.length,
      failed: errors.length,
      files: results,
      errors: errors
    };
  });
}

/** @deprecated alias */
function uploadToDrive(file) {
  return uploadToDriveWithPath(file);
}

function listUploadedFiles() {
  return fileStore.getAll();
}

module.exports = {
  uploadToDrive: uploadToDrive,
  uploadToDriveWithPath: uploadToDriveWithPath,
  uploadBatch: uploadBatch,
  listUploadedFiles: listUploadedFiles,
  buildFallbackFolderLink: buildFallbackFolderLink
};

/**
 * API routes: upload file/folder, list uploaded files, health
 */
var express = require('express');
var multer = require('multer');
var path = require('path');
var fs = require('fs');
var config = require('../config');
var driveService = require('../driveService');

var router = express.Router();

var UPLOAD_DIR = path.join(__dirname, '..', '..', 'uploads');
if (!fs.existsSync(UPLOAD_DIR)) {
  fs.mkdirSync(UPLOAD_DIR, { recursive: true });
}

var storage = multer.diskStorage({
  destination: function (req, file, cb) {
    cb(null, UPLOAD_DIR);
  },
  filename: function (req, file, cb) {
    var unique = Date.now() + '-' + Math.round(Math.random() * 1e9);
    var safeName = file.originalname.replace(/[^\w.\-()\/ ]/g, '_');
    cb(null, unique + '-' + safeName);
  }
});

// Khong gioi han dung luong file (chi gioi han boi Google Drive / o dia)
var upload = multer({
  storage: storage
});

var uploadFields = upload.fields([
  { name: 'file', maxCount: 1 },
  { name: 'files', maxCount: 50000 }
]);

function collectUploadedFiles(req) {
  var list = [];
  if (req.files) {
    if (req.files.file) {
      list = list.concat(req.files.file);
    }
    if (req.files.files) {
      list = list.concat(req.files.files);
    }
  }
  if (req.file) {
    list.push(req.file);
  }
  return list;
}

router.get('/status', function (req, res) {
  res.json({
    oauthConfigured: config.hasOAuthCredentials(),
    uploadReady: config.canUpload(),
    folderIdSet: !!config.google.driveFolderId,
    refreshTokenSet: !!config.google.refreshToken
  });
});

/**
 * POST /api/upload
 * - 1 file: field "file"
 * - nhieu file / folder: field "files" (filename = duong dan tuong doi)
 */
router.post('/upload', uploadFields, function (req, res) {
  if (!config.canUpload()) {
    return res.status(503).json({
      success: false,
      message:
        'Chưa sẵn sàng upload. Kiểm tra GOOGLE_REFRESH_TOKEN và GOOGLE_DRIVE_FOLDER_ID trong .env. ' +
        'Dùng /auth/google để lấy refresh token.'
    });
  }

  var files = collectUploadedFiles(req);
  if (!files.length) {
    return res.status(400).json({
      success: false,
      message: 'Không có file. Gửi field "file" hoặc "files".'
    });
  }

  if (files.length === 1) {
    driveService
      .uploadToDriveWithPath(files[0])
      .then(function (result) {
        res.json({
          success: true,
          message: 'Upload thành công',
          data: {
            fileId: result.fileId,
            fileName: result.fileName,
            relativePath: result.relativePath,
            webViewLink: result.webViewLink,
            webContentLink: result.webContentLink,
            size: result.size
          }
        });
      })
      .catch(function (err) {
        res.status(500).json({
          success: false,
          message: err.message || 'Upload thất bại'
        });
      });
    return;
  }

  driveService
    .uploadBatch(files)
    .then(function (batch) {
      var ok = batch.failed === 0;
      res.status(ok ? 200 : 207).json({
        success: ok,
        message:
          'Đã upload ' +
          batch.succeeded +
          '/' +
          batch.total +
          ' file' +
          (batch.failed ? ' (' + batch.failed + ' lỗi)' : ''),
        data: batch
      });
    })
    .catch(function (err) {
      res.status(500).json({
        success: false,
        message: err.message || 'Upload thất bại'
      });
    });
});

router.get('/files', function (req, res) {
  try {
    var files = driveService.listUploadedFiles();
    res.json({ success: true, files: files });
  } catch (err) {
    res.status(500).json({ success: false, message: err.message });
  }
});

module.exports = router;

/**
 * Frontend: file + folder upload, drag & drop, progress, danh sach
 */
(function () {
  var dropZone = document.getElementById('dropZone');
  var fileInput = document.getElementById('fileInput');
  var folderInput = document.getElementById('folderInput');
  var selectedFileBox = document.getElementById('selectedFileBox');
  var selectedFileName = document.getElementById('selectedFileName');
  var selectedFileSize = document.getElementById('selectedFileSize');
  var selectedFileList = document.getElementById('selectedFileList');
  var clearFileBtn = document.getElementById('clearFileBtn');
  var uploadBtn = document.getElementById('uploadBtn');
  var progressWrap = document.getElementById('progressWrap');
  var progressBar = document.getElementById('progressBar');
  var progressPercent = document.getElementById('progressPercent');
  var progressLabel = document.getElementById('progressLabel');
  var filesList = document.getElementById('filesList');
  var filesEmpty = document.getElementById('filesEmpty');
  var refreshListBtn = document.getElementById('refreshListBtn');
  var configBadge = document.getElementById('configBadge');
  var toastContainer = document.getElementById('toastContainer');

  /** @type {{ file: File, relativePath: string }[]} */
  var selectedItems = [];

  function formatBytes(bytes) {
    if (!bytes && bytes !== 0) return '-';
    var units = ['B', 'KB', 'MB', 'GB', 'TB'];
    var i = 0;
    var n = bytes;
    while (n >= 1024 && i < units.length - 1) {
      n /= 1024;
      i++;
    }
    return n.toFixed(i > 0 ? 1 : 0) + ' ' + units[i];
  }

  function totalBytes(items) {
    var sum = 0;
    for (var i = 0; i < items.length; i++) {
      sum += items[i].file.size || 0;
    }
    return sum;
  }

  function showToast(message, type) {
    var colors = {
      success: 'bg-emerald-600/95 border-emerald-400',
      error: 'bg-red-600/95 border-red-400',
      info: 'bg-slate-700/95 border-slate-500'
    };
    var el = document.createElement('div');
    el.className =
      'toast-enter pointer-events-auto px-4 py-3 rounded-lg border text-sm shadow-lg ' +
      (colors[type] || colors.info);
    el.textContent = message;
    toastContainer.appendChild(el);
    setTimeout(function () {
      el.style.opacity = '0';
      el.style.transition = 'opacity 0.3s';
      setTimeout(function () {
        if (el.parentNode) el.parentNode.removeChild(el);
      }, 300);
    }, 5000);
  }

  function itemsFromFileList(fileList) {
    var items = [];
    if (!fileList) return items;
    for (var i = 0; i < fileList.length; i++) {
      var f = fileList[i];
      var rel = f.webkitRelativePath || f.name;
      items.push({ file: f, relativePath: rel });
    }
    return items;
  }

  function setSelectedItems(items) {
    selectedItems = items || [];
    if (!selectedItems.length) {
      selectedFileBox.classList.add('hidden');
      uploadBtn.disabled = true;
      fileInput.value = '';
      folderInput.value = '';
      return;
    }

    selectedFileBox.classList.remove('hidden');
    var count = selectedItems.length;
    var bytes = totalBytes(selectedItems);

    if (count === 1) {
      selectedFileName.textContent = selectedItems[0].relativePath;
    } else {
      selectedFileName.textContent = count + ' file';
    }
    selectedFileSize.textContent = formatBytes(bytes) + ' tong';

    selectedFileList.innerHTML = '';
    var showMax = Math.min(count, 20);
    for (var j = 0; j < showMax; j++) {
      var li = document.createElement('li');
      li.textContent = selectedItems[j].relativePath;
      selectedFileList.appendChild(li);
    }
    if (count > showMax) {
      var more = document.createElement('li');
      more.textContent = '... va ' + (count - showMax) + ' file khac';
      selectedFileList.appendChild(more);
    }

    uploadBtn.disabled = false;
  }

  function readEntry(entry, basePath) {
    return new Promise(function (resolve, reject) {
      if (entry.isFile) {
        entry.file(
          function (file) {
            resolve([{ file: file, relativePath: basePath + file.name }]);
          },
          reject
        );
      } else if (entry.isDirectory) {
        var reader = entry.createReader();
        var allEntries = [];

        function readBatch() {
          reader.readEntries(function (entries) {
            if (!entries.length) {
              var chain = Promise.resolve([]);
              var prefix = basePath + entry.name + '/';
              for (var i = 0; i < allEntries.length; i++) {
                (function (ent) {
                  chain = chain.then(function (acc) {
                    return readEntry(ent, prefix).then(function (sub) {
                      return acc.concat(sub);
                    });
                  });
                })(allEntries[i]);
              }
              chain.then(resolve).catch(reject);
              return;
            }
            for (var j = 0; j < entries.length; j++) {
              allEntries.push(entries[j]);
            }
            readBatch();
          }, reject);
        }

        readBatch();
      } else {
        resolve([]);
      }
    });
  }

  function itemsFromDataTransfer(dt) {
    if (!dt) return Promise.resolve([]);

    if (dt.items && dt.items.length) {
      var hasEntry = false;
      for (var i = 0; i < dt.items.length; i++) {
        if (dt.items[i].webkitGetAsEntry) {
          hasEntry = true;
          break;
        }
      }
      if (hasEntry) {
        var promises = [];
        for (var k = 0; k < dt.items.length; k++) {
          var item = dt.items[k];
          if (item.kind !== 'file') continue;
          var entry = item.webkitGetAsEntry();
          if (entry) {
            promises.push(readEntry(entry, ''));
          }
        }
        return Promise.all(promises).then(function (groups) {
          var merged = [];
          for (var g = 0; g < groups.length; g++) {
            merged = merged.concat(groups[g]);
          }
          return merged;
        });
      }
    }

    return Promise.resolve(itemsFromFileList(dt.files));
  }

  function handleDrop(e) {
    itemsFromDataTransfer(e.dataTransfer).then(function (items) {
      if (items.length) setSelectedItems(items);
      else showToast('Khong co file hop le', 'error');
    }).catch(function () {
      showToast('Khong doc duoc folder keo tha', 'error');
    });
  }

  ['dragenter', 'dragover'].forEach(function (ev) {
    dropZone.addEventListener(ev, function (e) {
      e.preventDefault();
      e.stopPropagation();
      dropZone.classList.add('drag-over');
    });
  });

  ['dragleave', 'drop'].forEach(function (ev) {
    dropZone.addEventListener(ev, function (e) {
      e.preventDefault();
      e.stopPropagation();
      dropZone.classList.remove('drag-over');
    });
  });

  dropZone.addEventListener('drop', handleDrop);

  fileInput.addEventListener('change', function () {
    setSelectedItems(itemsFromFileList(fileInput.files));
  });

  folderInput.addEventListener('change', function () {
    setSelectedItems(itemsFromFileList(folderInput.files));
  });

  clearFileBtn.addEventListener('click', function () {
    setSelectedItems([]);
  });

  function setProgress(percent, label) {
    progressWrap.classList.remove('hidden');
    progressBar.style.width = percent + '%';
    progressPercent.textContent = Math.round(percent) + '%';
    if (label) progressLabel.textContent = label;
  }

  function hideProgress() {
    progressWrap.classList.add('hidden');
    progressBar.style.width = '0%';
    progressPercent.textContent = '0%';
  }

  function uploadItems(items) {
    return new Promise(function (resolve, reject) {
      var formData = new FormData();
      var fieldName = items.length === 1 ? 'file' : 'files';

      for (var i = 0; i < items.length; i++) {
        formData.append(fieldName, items[i].file, items[i].relativePath);
      }

      var xhr = new XMLHttpRequest();
      xhr.open('POST', '/api/upload', true);

      xhr.upload.onprogress = function (e) {
        if (e.lengthComputable) {
          var pct = (e.loaded / e.total) * 100;
          setProgress(pct, 'Dang upload... (' + items.length + ' file)');
        }
      };

      xhr.onload = function () {
        var body;
        try {
          body = JSON.parse(xhr.responseText);
        } catch (err) {
          return reject(new Error('Phan hoi server khong hop le'));
        }
        if (xhr.status >= 200 && xhr.status < 300 && body.success) {
          resolve(body);
        } else if (xhr.status === 207 && body.data) {
          resolve(body);
        } else {
          reject(new Error(body.message || 'Upload that bai'));
        }
      };

      xhr.onerror = function () {
        reject(new Error('Loi ket noi mang'));
      };

      xhr.send(formData);
    });
  }

  uploadBtn.addEventListener('click', function () {
    if (!selectedItems.length) {
      showToast('Vui long chon file hoac folder', 'error');
      return;
    }

    uploadBtn.disabled = true;
    setProgress(0, 'Bat dau upload...');

    uploadItems(selectedItems)
      .then(function (res) {
        setProgress(100, 'Hoan tat');
        if (res.data && res.data.files) {
          var batch = res.data;
          showToast(res.message || ('Upload ' + batch.succeeded + '/' + batch.total), batch.failed ? 'info' : 'success');
          if (batch.errors && batch.errors.length) {
            console.warn('Upload errors', batch.errors);
          }
        } else if (res.data && res.data.fileName) {
          showToast('Upload thanh cong: ' + res.data.fileName, 'success');
        } else {
          showToast(res.message || 'Upload thanh cong', 'success');
        }
        setSelectedItems([]);
        loadFiles();
        setTimeout(hideProgress, 800);
      })
      .catch(function (err) {
        hideProgress();
        showToast(err.message || 'Upload that bai', 'error');
      })
      .finally(function () {
        uploadBtn.disabled = !selectedItems.length;
      });
  });

  function renderFiles(files) {
    var items = filesList.querySelectorAll('.file-item');
    for (var i = 0; i < items.length; i++) {
      items[i].parentNode.removeChild(items[i]);
    }

    if (!files || !files.length) {
      filesEmpty.classList.remove('hidden');
      return;
    }

    filesEmpty.classList.add('hidden');

    files.forEach(function (f) {
      var row = document.createElement('div');
      row.className = 'file-item p-5 md:p-6 hover:bg-white/[0.02] transition';

      var displayName = f.relativePath || f.fileName;
      var viewLink = f.webViewLink || '#';
      var contentLink = f.webContentLink
        ? '<a href="' + escapeAttr(f.webContentLink) + '" target="_blank" rel="noopener" class="text-sm text-slate-400 hover:text-indigo-400">Tai xuong</a>'
        : '';

      row.innerHTML =
        '<div class="flex flex-col sm:flex-row sm:items-start justify-between gap-3">' +
        '<div class="min-w-0 flex-1">' +
        '<p class="font-medium text-slate-100 truncate">' + escapeHtml(displayName) + '</p>' +
        '<p class="text-sm text-slate-500 mt-1">' + formatBytes(f.size) + '</p>' +
        '<p class="text-xs text-slate-600 mt-1">' + escapeHtml(f.uploadedAt || '') + '</p>' +
        '</div>' +
        '<div class="flex flex-wrap gap-3 shrink-0">' +
        '<a href="' + escapeAttr(viewLink) + '" target="_blank" rel="noopener" class="text-sm font-medium text-indigo-400 hover:text-indigo-300">Mo tren Drive</a>' +
        contentLink +
        '</div></div>';

      filesList.appendChild(row);
    });
  }

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = s == null ? '' : String(s);
    return d.innerHTML;
  }

  function escapeAttr(s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/"/g, '&quot;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }

  function loadFiles() {
    fetch('/api/files')
      .then(function (r) {
        return r.json();
      })
      .then(function (data) {
        if (data.success) renderFiles(data.files);
      })
      .catch(function () {
        showToast('Khong tai duoc danh sach file', 'error');
      });
  }

  function loadStatus() {
    fetch('/api/status')
      .then(function (r) {
        return r.json();
      })
      .then(function (s) {
        if (s.uploadReady) {
          configBadge.textContent = 'San sang upload';
          configBadge.className =
            'text-xs px-3 py-1 rounded-full bg-emerald-500/20 text-emerald-400 border border-emerald-500/30';
        } else if (s.oauthConfigured) {
          configBadge.textContent = 'Can refresh token / folder ID';
          configBadge.className =
            'text-xs px-3 py-1 rounded-full bg-amber-500/20 text-amber-400 border border-amber-500/30';
        } else {
          configBadge.textContent = 'Chua cau hinh .env';
          configBadge.className =
            'text-xs px-3 py-1 rounded-full bg-red-500/20 text-red-400 border border-red-500/30';
        }
      })
      .catch(function () {
        configBadge.textContent = 'Server loi';
      });
  }

  refreshListBtn.addEventListener('click', loadFiles);
  loadStatus();
  loadFiles();
})();

/* CMS Upload - UI only */

.cms-card {
  transition: box-shadow 0.25s ease, border-color 0.25s ease;
}

.cms-card:hover {
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.35);
}

/* Buttons */
.btn-primary {
  background: linear-gradient(135deg, #3b82f6 0%, #6366f1 50%, #8b5cf6 100%);
  box-shadow: 0 4px 20px rgba(99, 102, 241, 0.35);
  transition: transform 0.15s ease, box-shadow 0.2s ease, filter 0.2s ease;
}

.btn-primary:hover:not(:disabled) {
  filter: brightness(1.08);
  transform: translateY(-1px);
  box-shadow: 0 8px 28px rgba(99, 102, 241, 0.45);
}

.btn-primary:active:not(:disabled) {
  transform: translateY(0);
}

.btn-secondary {
  font-size: 0.875rem;
  font-weight: 500;
  padding: 0.5rem 1rem;
  border-radius: 0.75rem;
  background: rgb(30 41 59);
  border: 1px solid rgb(71 85 105);
  color: rgb(226 232 240);
  transition: background 0.2s, border-color 0.2s, color 0.2s;
}

.btn-secondary:hover {
  background: rgb(51 65 85);
  border-color: rgb(100 116 139);
}

/* Drop zone */
.drop-zone.drag-over {
  border-color: rgb(99 102 241);
  background-color: rgba(99, 102, 241, 0.1);
  transform: scale(1.005);
  box-shadow: inset 0 0 0 1px rgba(99, 102, 241, 0.3);
}

.drop-zone {
  transition: border-color 0.2s, background-color 0.2s, transform 0.15s, box-shadow 0.2s;
}

/* Progress */
.progress-bar-fill {
  background: linear-gradient(90deg, #3b82f6, #6366f1, #a78bfa);
  background-size: 200% 100%;
  animation: progressShine 2s ease infinite;
}

.progress-wrap-done .progress-bar-fill {
  background: linear-gradient(90deg, #10b981, #34d399);
  animation: none;
}

@keyframes progressShine {
  0% { background-position: 100% 0; }
  100% { background-position: -100% 0; }
}

/* Upload button loading */
#uploadBtn.is-loading .upload-btn-icon {
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Config badge connected */
#configBadge.badge-connected .config-dot {
  background-color: #34d399;
  box-shadow: 0 0 8px rgba(52, 211, 153, 0.8);
  animation: pulseDot 2s ease infinite;
}

@keyframes pulseDot {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

/* Toast */
.toast-enter {
  animation: toastIn 0.35s ease-out forwards;
}

.toast-cms {
  pointer-events: auto;
  border-radius: 0.75rem;
  padding: 0.875rem 1rem;
  font-size: 0.875rem;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
}

@keyframes toastIn {
  from {
    opacity: 0;
    transform: translateX(1rem);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* File list table (rows injected by app.js) */
.files-table-wrap .file-item {
  border-bottom: 1px solid rgba(51, 65, 85, 0.5);
}

.files-table-wrap .file-item:last-child {
  border-bottom: none;
}

.file-row-inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  padding: 1rem 1.5rem;
  transition: background 0.15s;
}

@media (min-width: 640px) {
  .file-row-inner {
    grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) minmax(0, 1fr) auto;
    align-items: center;
    padding: 1rem 2rem;
  }
}

.file-row-inner:hover {
  background: rgba(255, 255, 255, 0.02);
}

.file-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.75rem;
  font-weight: 500;
  padding: 0.25rem 0.625rem;
  border-radius: 9999px;
  background: rgba(16, 185, 129, 0.15);
  color: #6ee7b7;
  border: 1px solid rgba(16, 185, 129, 0.25);
}

.file-action-link {
  font-size: 0.8125rem;
  font-weight: 500;
  color: #818cf8;
  text-decoration: none;
  transition: color 0.15s;
}

.file-action-link:hover {
  color: #a5b4fc;
}

.empty-state {
  display: block;
}

/* Result card reveal */
#resultCard.result-show {
  animation: resultIn 0.4s ease-out;
}

@keyframes resultIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Mobile table scroll hint */
@media (max-width: 639px) {
  .file-row-actions {
    flex-wrap: wrap;
  }
}

