var selectedItems = [];

function hideResultCard() {
  if (!resultCard) return;
  resultCard.classList.add('hidden');
  resultCard.classList.remove('result-show');
}

function showResultCard(data) {
  if (!resultCard || !data) return;
  var name = data.fileName || data.relativePath || '-';
  var id = data.fileId || '-';
  var view = data.webViewLink || '';
  var download = data.webContentLink || '';

  lastResultViewUrl = view;
  if (resultFileName) resultFileName.textContent = name;
  if (resultFileId) resultFileId.textContent = id;
  if (resultViewLink) resultViewLink.textContent = view || '-';
  if (resultOpenBtn) {
    resultOpenBtn.href = view || '#';
    if (!view) resultOpenBtn.classList.add('pointer-events-none', 'opacity-50');
    else resultOpenBtn.classList.remove('pointer-events-none', 'opacity-50');
  }
  if (resultDownloadWrap && resultDownloadLink) {
    if (download) {
      resultDownloadWrap.classList.remove('hidden');
      resultDownloadLink.textContent = download;
    } else {
      resultDownloadWrap.classList.add('hidden');
    }
  }
  resultCard.classList.remove('hidden');
  resultCard.classList.add('result-show');
  resultCard.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

if (resultCopyViewBtn) {
  resultCopyViewBtn.addEventListener('click', function () {
    if (!lastResultViewUrl) {
      showToast('Khong co link de copy', 'error');
      return;
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(lastResultViewUrl).then(function () {
        showToast('Da copy link Drive', 'success');
      }).catch(function () {
        showToast('Khong copy duoc link', 'error');
      });
    } else {
      showToast(lastResultViewUrl, 'info');
    }
  });
}

