/* Nhan dien thuong hieu truong hoc - #268752 */

:root {
  --brand-primary: #268752;
  --brand-hover: #1f6e44;
  --brand-light: #34a86b;
  --brand-muted: #e8f7ef;
  --brand-row-hover: #f0faf5;
  --bg-page: #f8fafc;
  --bg-alt: #f5f7f8;
  --bg-card: #ffffff;
  --border: #e5e7eb;
  --text: #1f2937;
  --text-muted: #6b7280;
}

body {
  background-color: var(--bg-page);
  color: var(--text);
}

.cms-page {
  max-width: 1400px;
}

/* Header truong */
.school-header {
  background: var(--brand-primary);
  color: #ffffff;
  box-shadow: 0 2px 12px rgba(38, 135, 82, 0.25);
}

.school-header a.header-link {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.15);
  border: 1px solid rgba(255, 255, 255, 0.35);
}

.school-header a.header-link:hover {
  background: rgba(255, 255, 255, 0.25);
}

.badge-header {
  background: rgba(255, 255, 255, 0.95);
  color: var(--brand-primary);
  border: none;
}

.badge-header.badge-warn {
  background: #fffbeb;
  color: #b45309;
}

.badge-header.badge-error {
  background: #fef2f2;
  color: #b91c1c;
}

/* Cards */
.cms-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 20px;
  box-shadow: 0 4px 24px rgba(15, 23, 42, 0.06);
  transition: box-shadow 0.25s ease;
}

.cms-card:hover {
  box-shadow: 0 8px 32px rgba(15, 23, 42, 0.08);
}

.cms-card-title {
  color: var(--brand-primary);
}

/* Buttons */
.btn-primary {
  background: var(--brand-primary);
  color: #ffffff;
  border: none;
  box-shadow: 0 2px 8px rgba(38, 135, 82, 0.3);
  transition: background 0.2s, transform 0.15s, box-shadow 0.2s;
}

.btn-primary:hover:not(:disabled) {
  background: var(--brand-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(31, 110, 68, 0.35);
}

.btn-primary:active:not(:disabled) {
  transform: translateY(0);
}

.btn-primary:focus-visible {
  outline: 2px solid var(--brand-light);
  outline-offset: 2px;
}

.btn-secondary {
  font-size: 0.875rem;
  font-weight: 500;
  padding: 0.5rem 1rem;
  border-radius: 10px;
  background: #ffffff;
  border: 1px solid var(--border);
  color: var(--text);
  transition: background 0.2s, border-color 0.2s, color 0.2s;
}

.btn-secondary:hover {
  background: var(--brand-muted);
  border-color: var(--brand-light);
  color: var(--brand-primary);
}

.btn-outline-brand {
  border-color: var(--brand-primary);
  color: var(--brand-primary);
}

.btn-outline-brand:hover {
  background: var(--brand-muted);
}

/* Drop zone */
.drop-zone {
  background: var(--bg-alt);
  border: 2px dashed #cbd5e1;
  transition: border-color 0.2s, background-color 0.2s, transform 0.15s;
}

.drop-zone:hover {
  border-color: var(--brand-light);
  background: var(--brand-muted);
}

.drop-zone.drag-over {
  border-color: var(--brand-primary);
  background: var(--brand-muted);
  transform: scale(1.002);
  box-shadow: inset 0 0 0 1px rgba(38, 135, 82, 0.2);
}

.drop-zone-icon {
  background: #ffffff;
  border: 1px solid var(--border);
  color: var(--brand-primary);
}

/* Selected files box */
.selected-box {
  background: var(--brand-muted);
  border: 1px solid rgba(38, 135, 82, 0.25);
}

.selected-box .size-text {
  color: var(--brand-primary);
  font-weight: 600;
}

/* Progress */
.progress-track {
  background: #e5e7eb;
  border: none;
}

.progress-bar-fill {
  background: var(--brand-primary);
  transition: width 0.3s ease;
}

.progress-wrap-done .progress-bar-fill {
  background: var(--brand-hover);
}

.progress-percent {
  color: var(--brand-primary);
  font-weight: 600;
}

#uploadBtn.is-loading .upload-btn-icon {
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Badge Connected (header) */
#configBadge.badge-connected {
  background: var(--brand-muted);
  color: var(--brand-primary);
}

#configBadge.badge-connected .config-dot {
  background-color: var(--brand-primary);
  animation: pulseDot 2s ease infinite;
}

@keyframes pulseDot {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.45; }
}

/* Result card */
.result-card {
  border: 1px solid rgba(38, 135, 82, 0.35);
  background: #ffffff;
}

.result-card-header {
  background: var(--brand-muted);
  border-bottom: 1px solid rgba(38, 135, 82, 0.2);
}

.result-card-header h2 {
  color: var(--brand-hover);
}

.result-field {
  background: var(--bg-alt);
  border: 1px solid var(--border);
}

.result-link-text {
  color: var(--brand-primary);
}

/* File table - quan ly dao tao */
.files-grid-header {
  display: none;
  grid-template-columns: 1fr;
  gap: 0.75rem;
  padding: 0.875rem 1.5rem;
  background: var(--brand-primary);
  color: #ffffff;
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.files-grid-header.is-visible {
  display: grid;
}

@media (min-width: 768px) {
  .files-grid-header.is-visible {
    grid-template-columns: minmax(0, 2.2fr) minmax(0, 1fr) minmax(0, 0.8fr) minmax(0, 1.2fr);
  }
}

.files-table-wrap .file-item {
  border-bottom: 1px solid var(--border);
  background: #ffffff;
}

.files-table-wrap .file-item:last-child {
  border-bottom: none;
}

.file-row-inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.75rem;
  padding: 1rem 1.5rem;
  transition: background 0.15s;
}

@media (min-width: 768px) {
  .file-row-inner {
    grid-template-columns: minmax(0, 2.2fr) minmax(0, 1fr) minmax(0, 0.8fr) minmax(0, 1.2fr);
    align-items: center;
  }
}

.file-row-inner:hover {
  background: var(--brand-row-hover);
}

.file-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.75rem;
  font-weight: 500;
  padding: 0.25rem 0.625rem;
  border-radius: 9999px;
  background: var(--brand-muted);
  color: var(--brand-primary);
  border: 1px solid rgba(38, 135, 82, 0.2);
}

.file-status-badge .status-dot {
  background-color: var(--brand-primary);
}

.file-action-link {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--brand-primary);
  text-decoration: none;
  transition: color 0.15s;
}

.file-action-link:hover {
  color: var(--brand-hover);
  text-decoration: underline;
}

.empty-state {
  display: block;
  color: var(--text-muted);
}

.empty-state-icon {
  background: var(--brand-muted);
  border: 1px solid rgba(38, 135, 82, 0.15);
  color: var(--brand-primary);
}

/* Toast */
.toast-enter {
  animation: toastIn 0.35s ease-out forwards;
}

.toast-cms {
  pointer-events: auto;
  border-radius: 10px;
  padding: 0.875rem 1rem;
  font-size: 0.875rem;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
}

.toast-success {
  background: var(--brand-muted);
  border: 1px solid rgba(38, 135, 82, 0.35);
  color: var(--brand-hover);
}

.toast-error {
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #b91c1c;
}

.toast-info {
  background: #ffffff;
  border: 1px solid var(--border);
  color: var(--text);
}

@keyframes toastIn {
  from {
    opacity: 0;
    transform: translateX(1rem);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

#resultCard.result-show {
  animation: resultIn 0.4s ease-out;
}

@keyframes resultIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 767px) {
  .file-row-actions {
    flex-wrap: wrap;
  }
}

