/* CMS truong hoc - gon, #268752 */

:root {
  --brand-primary: #268752;
  --brand-hover: #1f6e44;
  --brand-light: #34a86b;
  --brand-muted: #e8f7ef;
  --brand-row-hover: #f0faf5;
  --bg-page: #f8fafc;
  --bg-alt: #f5f7f8;
  --bg-card: #ffffff;
  --border: #e5e7eb;
  --radius: 8px;
  --text: #1f2937;
  --text-muted: #6b7280;
}

body {
  background-color: var(--bg-page);
  color: var(--text);
  font-size: 14px;
}

.cms-page {
  max-width: 1200px;
}

/* Header */
.school-header {
  background: var(--brand-primary);
  color: #ffffff;
  box-shadow: none;
}

.school-header a.header-link {
  color: #ffffff;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.3);
}

.school-header a.header-link:hover {
  background: rgba(255, 255, 255, 0.2);
}

.badge-header {
  background: rgba(255, 255, 255, 0.95);
  color: var(--brand-primary);
}

.badge-header.badge-warn {
  background: #fffbeb;
  color: #b45309;
}

.badge-header.badge-error {
  background: #fef2f2;
  color: #b91c1c;
}

/* Cards - form quan tri */
.cms-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.05);
}

.cms-card:hover {
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.08);
}

.cms-card-title {
  color: var(--brand-primary);
}

.card-head {
  padding: 12px 20px;
}

/* Buttons */
.btn-primary {
  background: var(--brand-primary);
  color: #ffffff;
  border: none;
  box-shadow: none;
  transition: background 0.15s;
}

.btn-primary:hover:not(:disabled) {
  background: var(--brand-hover);
  transform: none;
  box-shadow: none;
}

.btn-primary:focus-visible {
  outline: 2px solid var(--brand-light);
  outline-offset: 1px;
}

.btn-secondary {
  font-size: 0.75rem;
