function shortenFileId(id) {
  if (!id) return '';
  var s = String(id);
  if (s.length <= 24) return s;
  return s.substring(0, 10) + '...' + s.substring(s.length - 8);
}

function updateFilesPagination(total) {
  if (!filesPagination) return;
  var totalPages = Math.max(1, Math.ceil(total / FILES_PAGE_SIZE));
  if (currentFilesPage > totalPages) {
    currentFilesPage = totalPages;
  }
  if (total <= FILES_PAGE_SIZE) {
    filesPagination.classList.add('hidden');
    return;
  }
  filesPagination.classList.remove('hidden');
  var start = (currentFilesPage - 1) * FILES_PAGE_SIZE + 1;
  var end = Math.min(currentFilesPage * FILES_PAGE_SIZE, total);
  if (filesPageInfo) {
    filesPageInfo.textContent = 'Hien thi ' + start + '-' + end + ' / ' + total + ' file';
  }
  if (filesPageNum) {
    filesPageNum.textContent = 'Trang ' + currentFilesPage + '/' + totalPages;
  }
  if (filesPrevBtn) {
    filesPrevBtn.disabled = currentFilesPage <= 1;
  }
  if (filesNextBtn) {
    filesNextBtn.disabled = currentFilesPage >= totalPages;
  }
}

function renderFilesPage() {
  var items = filesList.querySelectorAll('.file-item');
  for (var i = 0; i < items.length; i++) {
    items[i].parentNode.removeChild(items[i]);
  }

  var total = allFilesCache.length;
  if (!total) {
    filesEmpty.classList.remove('hidden');
    if (filesPagination) filesPagination.classList.add('hidden');
    return;
  }

  filesEmpty.classList.add('hidden');
  updateFilesPagination(total);

  var totalPages = Math.max(1, Math.ceil(total / FILES_PAGE_SIZE));
  if (currentFilesPage > totalPages) {
    currentFilesPage = totalPages;
  }
  var startIdx = (currentFilesPage - 1) * FILES_PAGE_SIZE;
  var pageFiles = allFilesCache.slice(startIdx, startIdx + FILES_PAGE_SIZE);

  pageFiles.forEach(function (f) {
    var row = document.createElement('div');
    row.className = 'file-item';

    var displayName = f.relativePath || f.fileName;
    var viewLink = f.webViewLink || '#';
    var uploadedAt = f.uploadedAt ? formatUploadDate(f.uploadedAt) : '-';
    var sizeText = formatBytes(f.size);
    var downloadBtn = f.webContentLink
      ? '<a href="' + escapeAttr(f.webContentLink) + '" target="_blank" rel="noopener" class="file-action-link">Tai</a>'
      : '';

    row.innerHTML =
      '<p class="file-card-name" title="' + escapeAttr(displayName) + '">' + escapeHtml(displayName) + '</p>' +
      '<p class="file-card-meta">' + escapeHtml(uploadedAt) + ' &middot; ' + escapeHtml(sizeText) + '</p>' +
      '<p class="file-card-id" title="' + escapeAttr(f.fileId || '') + '">' + escapeHtml(shortenFileId(f.fileId)) + '</p>' +
      '<div class="file-card-actions">' +
      '<span class="file-status-badge"><span class="rounded-full status-dot"></span>OK</span>' +
      '<a href="' + escapeAttr(viewLink) + '" target="_blank" rel="noopener" class="file-action-link">Drive</a>' +
      downloadBtn +
      '</div>';

    filesList.appendChild(row);
  });
}

function renderFiles(files) {
  allFilesCache = files || [];
  currentFilesPage = 1;
  renderFilesPage();
}

