function getBrowseEntries(files, browsePath) {
  browsePath = pathNorm(browsePath);
  var prefix = browsePath ? browsePath + '/' : '';
  var folderMap = {};
  var fileList = [];
  var i;
  var full;
  var rest;
  var parts;
  var folderName;

  for (i = 0; i < files.length; i++) {
    full = pathNorm(files[i].relativePath || files[i].fileName);
    if (!full) continue;
    if (browsePath) {
      if (full === browsePath) continue;
      if (full.indexOf(prefix) !== 0) continue;
      rest = full.substring(prefix.length);
    } else {
      rest = full;
