input.new_string:
function renderFilesPage() {
  closeDriveMenus();
  var items = filesList.querySelectorAll('.drive-item');
  for (var i = 0; i < items.length; i++) {
    items[i].parentNode.removeChild(items[i]);
  }

  if (!allFilesCache.length) {
    filesEmpty.classList.remove('hidden');
    if (filesPagination) filesPagination.classList.add('hidden');
    if (filesBreadcrumb) filesBreadcrumb.classList.add('hidden');
    if (filesToolbar) filesToolbar.classList.add('hidden');
    return;
  }

  filesEmpty.classList.add('hidden');
  renderBreadcrumb();

  browseEntriesCache = getBrowseEntries(allFilesCache, currentBrowsePath);
  var total = browseEntriesCache.length;

  if (!total) {
    filesEmpty.classList.remove('hidden');
    filesEmpty.querySelector('span.block').textContent = 'Thu muc trong';
    if (filesPagination) filesPagination.classList.add('hidden');
    return;
  }

  filesEmpty.classList.add('hidden');
  if (filesEmpty.querySelector('span.block')) {
    filesEmpty.querySelector('span.block').textContent = 'Chua co file nao';
  }

  updateFilesPagination(total);

  var totalPages = Math.max(1, Math.ceil(total / FILES_PAGE_SIZE));
  if (currentFilesPage > totalPages) {
    currentFilesPage = totalPages;
  }
  var startIdx = (currentFilesPage - 1) * FILES_PAGE_SIZE;
  var pageItems = browseEntriesCache.slice(startIdx, startIdx + FILES_PAGE_SIZE);

  pageItems.forEach(function (entry) {
    var row = document.createElement('div');
    row.className = 'drive-item';
    row.setAttribute('data-type', entry.type);

    var menuHtml;
    if (entry.type === 'folder') {
      row.setAttribute('data-path', entry.path);
      menuHtml =
        '<div class="drive-menu-pop hidden">' +
        '<button type="button" data-action="open-folder">Mo thu muc</button>' +
        '</div>';
      row.innerHTML =
        FOLDER_ICON_SVG +
        '<span class="drive-item-name" title="' + escapeAttr(entry.name) + '">' + escapeHtml(entry.name) + '</span>' +
        '<button type="button" class="drive-item-menu" aria-label="Menu">&#8942;</button>' +
        menuHtml;
    } else {
      var rec = entry.record;
      var viewLink = rec.webViewLink || '#';
      var dl = rec.webContentLink || '';
      var meta = (rec.uploadedAt ? formatUploadDate(rec.uploadedAt) : '-') + ' · ' + formatBytes(rec.size);
      row.setAttribute('data-view', viewLink);
      menuHtml = '<div class="drive-menu-pop hidden">';
      menuHtml += '<a href="' + escapeAttr(viewLink) + '" target="_blank" rel="noopener">Mo tren Drive</a>';
      if (dl) {
        menuHtml += '<a href="' + escapeAttr(dl) + '" target="_blank" rel="noopener">Tai xuong</a>';
      }
      menuHtml += '<button type="button" data-action="info">' + escapeHtml(meta) + '</button>';
      menuHtml += '</div>';
      row.innerHTML =
        fileIconHtml(rec) +
        '<span class="drive-item-name" title="' + escapeAttr(entry.name) + '">' + escapeHtml(entry.name) + '</span>' +
        '<button type="button" class="drive-item-menu" aria-label="Menu">&#8942;</button>' +
        menuHtml;
    }

    filesList.appendChild(row);
  });
}

function renderFiles(files) {
  allFilesCache = files || [];
  currentBrowsePath = '';
  currentFilesPage = 1;
  renderFilesPage();
}

if (filesBreadcrumb) {
  filesBreadcrumb.addEventListener('click', function (e) {
    var btn = e.target.closest('.drive-crumb[data-path]');
    if (!btn) return;
    currentBrowsePath = btn.getAttribute('data-path') || '';
    currentFilesPage = 1;
    renderFilesPage();
  });
}

if (filesList) {
  filesList.addEventListener('click', function (e) {
    var menuBtn = e.target.closest('.drive-item-menu');
    if (menuBtn) {
      e.stopPropagation();
      var pop = menuBtn.parentNode.querySelector('.drive-menu-pop');
      if (!pop) return;
      if (openDriveMenu === pop) {
        closeDriveMenus();
        return;
      }
      closeDriveMenus();
      pop.classList.remove('hidden');
      openDriveMenu = pop;
      return;
    }

    var actionBtn = e.target.closest('[data-action]');
    if (actionBtn) {
      e.stopPropagation();
      var item = actionBtn.closest('.drive-item');
      if (actionBtn.getAttribute('data-action') === 'open-folder' && item) {
        currentBrowsePath = item.getAttribute('data-path') || '';
        currentFilesPage = 1;
        renderFilesPage();
      }
      closeDriveMenus();
      return;
    }

    if (e.target.closest('.drive-menu-pop')) {
      return;
    }

    var row = e.target.closest('.drive-item');
    if (!row) return;
    if (row.getAttribute('data-type') === 'folder') {
      currentBrowsePath = row.getAttribute('data-path') || '';
      currentFilesPage = 1;
      renderFilesPage();
    } else {
      var link = row.getAttribute('data-view');
      if (link && link !== '#') {
        window.open(link, '_blank');
      }
    }
  });
}

document.addEventListener('click', function (e) {
  if (!e.target.closest('.drive-item')) {
    closeDriveMenus();
  }
});

